/**
 * Contracts shared INSIDE the Electron UI app (main ⇄ preload ⇄ renderer):
 * the IPC surface, persisted settings, CLI detection and the daemon connection
 * handle. Nothing here describes the daemon's HTTP API, and there are no secret
 * identifiers — the app stores no credentials (see the Secrets section below).
 *
 * The daemon's wire shapes are NOT mirrored here. They are generated from its
 * own OpenAPI document into `apps/ui/src/renderer/autogenerated` by
 * `pnpm generate:api`, and the renderer imports them from there — so a route or
 * schema change on the daemon surfaces as a type error after regeneration
 * instead of silently drifting from a hand-written copy.
 */

// ─────────────────────────────────────────────────────────────────────────────
// Daemon connection (read from the pidfile by main, passed to the renderer)
// ─────────────────────────────────────────────────────────────────────────────

/** Connection coordinates the renderer needs to open an authed WS/HTTP call. */
export interface DaemonHandle {
  /** Loopback host the daemon reported binding to (from the pidfile). */
  host: string;
  /** Loopback port the daemon reported binding to. */
  port: number;
  /** Per-launch bearer token; required on every daemon request. */
  token: string;
  /** Daemon version (semver). */
  version: string;
}

/** Live status the renderer polls/subscribes to for the connection banner. */
export interface DaemonStatus {
  connected: boolean;
  handle: DaemonHandle | null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Settings (non-secret app config — persisted as JSON in userData)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Bounds on the saved run configurations. Here rather than beside the IPC
 * schema because three places must agree and only two are in main: that schema,
 * the settings READ path (which salvages entry-by-entry and so never evaluates
 * the array bound), and the renderer's editor, which refuses a save before the
 * IPC throws and discards the whole patch.
 */
export const MAX_RUN_CONFIGS = 50;
export const MAX_RUN_CONFIG_NAME = 80;

/**
 * A saved new-chat setup the user named — a bundle of COMPOSER state and
 * nothing more. Choosing one seeds the normal new-chat screen; it creates no
 * run and reaches the daemon only later, through the ordinary create call.
 *
 * The daemon-vocabulary fields (`target`, `model`, `effort`, `approval`) are
 * OPAQUE strings, as the single-value settings beside them are: this file holds
 * no daemon shapes, and the renderer checks each against the generated enum
 * before it reaches a run. `null` means "the CLI's own default" everywhere.
 */
export interface RunConfig {
  id: string;
  name: string;
  /** Absolute working directory the chat starts in. */
  cwd: string;
  /**
   * Branch the folder should be on, or null to take whatever is checked out.
   *
   * NOT a chat field — no branch reaches the daemon. Applying one is a guarded
   * `git switch` on `cwd` before the chat is created, which refuses over a dirty
   * tree; that refusal is surfaced and the rest of the configuration still
   * applies.
   */
  branch: string | null;
  /** The composer target — a CLI kind or `wf:<slug>`, exactly as `lastChatTarget`. */
  target: string;
  model: string | null;
  effort: string | null;
  /** The daemon's `ChatApprovalMode`. */
  approval: string | null;
  /** Plugin/profile directory, or null for the CLI's own account. */
  configDir: string | null;
}

/** Persisted, non-secret application settings. Secrets never live here. */
export interface Settings {
  /** First-run onboarding finished (gates the renderer's initial route). */
  onboardingComplete: boolean;
  /** Absolute path to the user's working project folder (agent cwd). */
  projectFolder: string | null;
  /** Recently used project folders, most recent first (composer suggestions). */
  recentFolders: string[];
  /**
   * Plugin directory the next new chat loads, or null for none — the composer's
   * optional companion to `projectFolder`, so a user who works under one plugin
   * set (a different subscription, a different toolbelt) does not re-pick it per
   * chat. Each chat records its OWN, so this is only the picker's default.
   */
  configDir: string | null;
  /** Recently used plugin directories, most recent first (picker rows). */
  recentConfigDirs: string[];
  /**
   * The user's saved new-chat setups (see {@link RunConfig}). A managed LIST,
   * unlike `recentFolders`/`recentConfigDirs` beside it: nothing adds or evicts
   * an entry, and the order is the user's, so it is never re-sorted on read.
   */
  runConfigs: RunConfig[];
  /** The chat composer's last target — a CLI kind or `wf:<slug>`. */
  lastChatTarget: string | null;
  /**
   * The new-run composer's last approval mode, so it opens on the choice the
   * user actually works in rather than resetting to `ask` every time. An
   * opaque string here on purpose: the mode vocabulary is the DAEMON's (its
   * `ChatApprovalMode`), and this file holds no daemon shapes — the renderer
   * validates the stored value against the generated enum before applying it.
   */
  lastApprovalMode: string | null;
  /**
   * The new-run composer's last model per CLI. Keyed by CLI because the two
   * have disjoint model vocabularies — one shared slot would hand cursor a
   * claude alias the moment the user switched agents. A missing entry means
   * that CLI's own default (no `--model` flag).
   */
  lastModels: Partial<Record<CliKind, string>>;
  /**
   * The new-run composer's last reasoning-effort level per CLI. Keyed per CLI
   * for the same reason as `lastModels`, and opaque here for the same reason
   * as `lastApprovalMode`: the vocabulary belongs to the CLI (the daemon asks
   * its adapter), so this file cannot name the levels. A missing entry means
   * that CLI's own default — which is also every CLI that has no such control.
   */
  lastEfforts: Partial<Record<CliKind, string>>;
  /** Explicit overrides for CLI binary locations (else resolved on PATH). */
  cliPaths: Partial<Record<CliKind, string>>;
  /** Whether to check for app updates on launch (wired in M4). */
  checkForUpdates: boolean;
  /**
   * Whether the left nav rail is collapsed to its icon-only width.
   *
   * Persisted rather than session state because the rail is the one piece of
   * chrome a user sets ONCE to suit how they work — a wide window with the
   * labels on, a narrow one without — and re-collapsing it on every launch
   * made the choice look like it had not been taken.
   */
  sidebarCollapsed: boolean;
  /**
   * Post system notifications — a banner outside the app when an agent stops to
   * ask something, and when a thread's turn ends.
   *
   * ONE switch for both, not one per kind: they are the same interruption seen
   * from two sides of the same turn, and a user who does not want the app
   * talking to them outside its window does not want half of it. Defaults ON —
   * a thread parked on a question nobody sees is the failure this exists to
   * fix, so the useful state is the default and the switch is there to quiet
   * it.
   */
  notificationsEnabled: boolean;
  /**
   * Spawn the daemon with a Node inspector on loopback, so real Chrome
   * DevTools can attach to it from `chrome://inspect`.
   *
   * The daemon is a separate Node process, so the renderer's DevTools can see
   * nothing of it. This is what closes that gap, and it is the genuine article
   * rather than a reimplementation: Sources with breakpoints over the daemon's
   * own TypeScript, the CPU profiler, heap snapshots.
   *
   * **Three states, not two.** `null` is "not chosen", which resolves per
   * build — on in dev, off when packaged (`resolveDaemonInspect`) — and an
   * explicit boolean overrides that either way.
   *
   * A plain boolean could not express this, because dev and the packaged app
   * share ONE userData dir (`app.setName('Geniro')` decides it, and both
   * builds set the same name). Whatever a dev launch resolved would be
   * written to the same settings.json a shipped launch then reads, so a
   * boolean default would leak the dev answer into the packaged build — the
   * exact case the split exists to prevent.
   */
  daemonInspect: boolean | null;
  /**
   * Let a claude chat drive the user's browser through **Claude in Chrome**.
   *
   * The CLI ships those tools (`mcp__claude-in-chrome__*` — navigate, read the
   * page, fill a form, run JS, read the console and network) and withholds them
   * from the headless mode geniro drives, so this switch is what hands them
   * back. OFF by default, unlike the other two tool families geniro restores:
   * this one does nothing at all without Anthropic's Chrome extension
   * installed and a browser running it, and it is 22 tool schemas in every
   * prompt of every turn — a cost paid per turn for a toolbelt most runs never
   * touch.
   *
   * Read when the daemon PROCESS is launched (it rides its env), so flipping it
   * respawns the daemon, exactly like the CLI paths and the inspector.
   */
  claudeBrowserTools: boolean;
}

/** Default settings written on first launch when no settings file exists. */
export const DEFAULT_SETTINGS: Settings = {
  onboardingComplete: false,
  projectFolder: null,
  recentFolders: [],
  configDir: null,
  recentConfigDirs: [],
  runConfigs: [],
  lastChatTarget: null,
  lastApprovalMode: null,
  lastModels: {},
  lastEfforts: {},
  cliPaths: {},
  checkForUpdates: true,
  sidebarCollapsed: false,
  notificationsEnabled: true,
  daemonInspect: null,
  claudeBrowserTools: false,
};

/**
 * Whether this launch spawns the daemon with an inspector.
 *
 * Unchosen means ON in dev and OFF when packaged, which is the honest default
 * on both sides rather than one compromise for both. Developing the app is
 * debugging it — there is no argument for making that a click — while a
 * shipped install has a user who will never attach a debugger and gains
 * nothing from the port, so the only thing an always-on default would add
 * there is arbitrary code execution inside the daemon for anything that
 * reaches loopback. That daemon spawns CLIs with the user's own permissions
 * over their source tree, and its env can still carry a credential the user
 * exported themselves — geniro no longer puts one there, which lowers the
 * stakes without removing them.
 *
 * (Node's inspector does validate the `Host` header, so a random web page
 * cannot attach — the exposure is to local processes, not to the network.
 * That is a real limit on the risk, and still not zero.)
 *
 * An explicit choice always wins, in both directions: a developer who
 * switched it off keeps it off, and a user who switched it on in a packaged
 * build keeps it on.
 */
export function resolveDaemonInspect(
  setting: boolean | null,
  isPackaged: boolean,
): boolean {
  return setting ?? !isPackaged;
}

/**
 * Loopback port the daemon's inspector listens on when `daemonInspect` is on.
 *
 * 9229 deliberately — it is node's own default, and the one address
 * `chrome://inspect` discovers with no configuration. A tidier private port
 * would mean every user's first step is "add 127.0.0.1:<x> under Configure",
 * which is the step people give up at.
 *
 * The Electron MAIN process is never launched with `--inspect` here, so
 * nothing else in this app claims it. If something outside does, node reports
 * the address as in use and the daemon still starts — the inspector is the
 * only thing lost.
 */
export const DAEMON_INSPECT_PORT = 9229;

// ─────────────────────────────────────────────────────────────────────────────
// App updates (GitHub Releases → download → checksum → swap the bundle in
// place; see main/update-service.ts and main/update-installer.ts)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Where the app is in noticing, fetching and applying an update.
 *
 * One phase list for both surfaces that show it — the banner over the views and
 * the Settings section — because they are two views of one process and a second
 * vocabulary is where the two would start disagreeing about what is happening.
 *
 * `ready` is the brief window between a swapped bundle and the relaunch: the
 * update is already ON DISK there, so a failure after it is not a failed update.
 */
export type UpdatePhase =
  | 'idle'
  | 'checking'
  | 'up-to-date'
  | 'available'
  | 'downloading'
  | 'installing'
  | 'ready'
  | 'error';

/** The whole of what main knows about updating, pushed on every change. */
export interface UpdateState {
  phase: UpdatePhase;
  /** The version being offered/fetched/installed; null when there is none. */
  version: string | null;
  /** 0–1 while `downloading`, null in every other phase. */
  progress: number | null;
  /** One line for the user: the failure, or what is happening right now. */
  message: string | null;
  /** The running app's version, so a screen can state it without a second call. */
  currentVersion: string;
  /**
   * Whether THIS install can replace itself.
   *
   * False for an unpackaged launch and for a bundle the user cannot write (a
   * copy owned by another account, a read-only mount, a translocated quarantine
   * copy). The surfaces read it to decide between an "Update now" button and
   * naming {@link UPDATE_COMMAND} — an update button that cannot work is worse
   * than a sentence saying which command does.
   */
  canInstall: boolean;
}

/** The one command that updates an install this app cannot replace itself. */
export const UPDATE_COMMAND = 'brew upgrade --cask geniro';

// ─────────────────────────────────────────────────────────────────────────────
// System notifications (a banner outside the app, for a thread nobody is
// watching — see main/notify.ts)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Why a thread is worth interrupting the user for.
 *
 * The renderer reports the KIND and main decides whether it becomes a banner —
 * the renderer never reads the toggle. That is what makes a flipped switch take
 * effect at once instead of whenever a screen last cached its settings, and it
 * keeps the one place that can post a banner the one place that gates it.
 */
export type RunNotificationKind = 'question' | 'turn-end';

/** One notification the renderer asks main to post. */
export interface RunNotification {
  kind: RunNotificationKind;
  /** The run it is about — clicking the banner opens this chat. */
  runId: string;
  /** The thread's sidebar label, so the banner names which chat. */
  title: string;
  /** One line under the title. */
  body: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// CLI detection
// ─────────────────────────────────────────────────────────────────────────────

/** CLI agents geniro can drive in v1 (all headless). */
export type CliKind = 'claude' | 'cursor-agent';

/** Every CLI kind, in onboarding display order. */
export const CLI_KINDS: readonly CliKind[] = ['claude', 'cursor-agent'];

/** Result of probing the host for a single CLI agent. */
export interface CliDetection {
  kind: CliKind;
  /** True when the binary was located and reported a version. */
  found: boolean;
  /** Absolute path to the resolved binary, when found. */
  path: string | null;
  /** Version string the binary reported, when found. */
  version: string | null;
  /**
   * Whether the CLI reports itself signed in, for a CLI that can be asked.
   *
   * Three states, and the third is why this is not a plain boolean: `true` /
   * `false` are answers the CLI gave, and `null` means nobody knows — either the
   * CLI has no status command to ask (claude, whose credentials the daemon
   * handles by other means) or the probe itself failed. A failed probe must NOT
   * read as signed-out: the readiness chip would tell the user to sign in when
   * they already are, and the sign-in it offers would fix nothing.
   */
  loggedIn: boolean | null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Git (the composer's branch chip — read from the folder a run will use)
// ─────────────────────────────────────────────────────────────────────────────

/** Git state of a working directory; every field is safe on a non-repo. */
export interface GitInfo {
  /** False for a plain folder — the branch chip renders only when true. */
  isRepo: boolean;
  /** Current branch, or null on a detached HEAD (no branch to name). */
  branch: string | null;
  /** Local branches, for the picker. */
  branches: string[];
  /** Working tree has uncommitted changes — blocks a branch switch. */
  dirty: boolean;
}

/** Outcome of a guarded branch switch. `branch` is the branch now checked out. */
export interface BranchSwitchResult {
  ok: boolean;
  branch: string | null;
  /** Why the switch was refused or failed; null on success. */
  error: string | null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Secrets — none. The app stores no credentials.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * `KEYCHAIN_SERVICE` and `SecretName` are deliberately GONE, along with
 * `keychain.ts` and the save/has/delete IPC channels.
 *
 * `cursor.apiKey` was the only secret this app ever held, and it stopped being
 * needed once `cursor-agent` was confirmed to authenticate from its own
 * `~/.cursor` login. `SecretName` could not simply lose its one member — zod
 * rejects an empty enum, so the IPC schema had no valid shape — which is what
 * made removing the surface the honest option rather than keeping a scaffold
 * with a placeholder member no caller could ever pass.
 *
 * The service name lives on as a literal in `purge-legacy-secret.ts`, whose one
 * job is deleting the entry earlier versions wrote.
 *
 * The project's "secrets live in the macOS Keychain only — never in SQLite,
 * never in a file" rule is NOT repealed by this. It still governs the moment a
 * second secret is ever needed; there simply is no first one now.
 */

// ─────────────────────────────────────────────────────────────────────────────
// IPC contract (window.geniro — exposed by the preload via contextBridge)
// ─────────────────────────────────────────────────────────────────────────────

/** Input captured by the onboarding flow and committed in one IPC call. */
export interface OnboardingInput {
  /** Per-agent binary path overrides (absolute paths); omitted keys auto-detect. */
  cliPaths?: Partial<Record<CliKind, string>>;
}

/**
 * The typed API surface the preload exposes on `window.geniro`. The renderer
 * never touches Node or Electron directly — every privileged action is one of
 * these channels.
 */
export interface GeniroApi {
  /** Current onboarding + daemon status. */
  getStatus(): Promise<{
    onboardingComplete: boolean;
    daemon: DaemonStatus;
    /**
     * Whether this is a packaged build. The renderer needs it for exactly one
     * thing: settings whose unchosen state resolves per build
     * (`resolveDaemonInspect`). A screen that showed the STORED `null` as
     * "off" would tell the user no debugger port is open while the dev daemon
     * is listening on one — and `import.meta.env.PROD` is not the same
     * question, since a built-but-unpackaged run answers it the other way.
     */
    isPackaged: boolean;
  }>;
  /** Daemon connection handle (host + port + token) for opening an authed WS. */
  getDaemonHandle(): Promise<DaemonHandle | null>;
  /** Subscribe to daemon restarts that rotate the loopback handle/token. */
  onDaemonRestarted(listener: (handle: DaemonHandle) => void): () => void;
  /** Open the native folder picker; returns the chosen absolute path or null. */
  pickProjectFolder(): Promise<string | null>;
  /** Open the native file picker for an agent binary; returns the path or null. */
  pickAgentBinary(): Promise<string | null>;
  /** Read the persisted settings. */
  getSettings(): Promise<Settings>;
  /** Merge a partial patch into settings; returns the updated settings. */
  updateSettings(patch: Partial<Settings>): Promise<Settings>;
  /** Probe the host for each supported CLI agent. */
  detectClis(): Promise<CliDetection[]>;
  /** Persist onboarding input and mark onboarding complete. */
  completeOnboarding(input: OnboardingInput): Promise<Settings>;
  /** Open a native picker for a workflow YAML to import; path or null. */
  pickWorkflowImport(): Promise<string | null>;
  /** Open a native save dialog for a workflow export; target path or null. */
  pickWorkflowExport(defaultName: string): Promise<string | null>;
  /** The current update state, for a screen that just mounted. */
  getUpdateState(): Promise<UpdateState>;
  /**
   * Check the GitHub Releases feed NOW, resolving with the resulting state.
   *
   * The same check the launch and the periodic timer run — a manual press is
   * not a second code path, it only skips the wait.
   */
  checkForUpdates(): Promise<UpdateState>;
  /**
   * Download, verify and swap in the available update.
   *
   * Resolves with the state at the END of the attempt: `error` when it could
   * not be applied, otherwise `ready`. It does NOT restart the app — see
   * {@link relaunchForUpdate}.
   */
  installUpdate(): Promise<UpdateState>;
  /**
   * Quit and come back up on the freshly-installed bundle.
   *
   * Separate from {@link installUpdate} because restarting takes the daemon and
   * every running turn with it, so the moment is the user's to pick. A no-op
   * unless an update is actually `ready`.
   */
  relaunchForUpdate(): Promise<UpdateState>;
  /** Subscribe to update-state changes (check progress, download progress). */
  onUpdateState(listener: (state: UpdateState) => void): () => void;
  /** Read a folder's git state (repo? branch? branches? dirty?). */
  getGitInfo(dir: string): Promise<GitInfo>;
  /**
   * Open the user's own terminal on a command — the handoff out of geniro.
   * Takes the command as DATA (never a shell string) so nothing here has to
   * quote it, and so the renderer cannot smuggle a second command in.
   */
  openInTerminal(input: {
    command: string;
    args: string[];
    cwd: string;
    /**
     * Env the invocation needs, composed by the DAEMON (the run's config
     * directory — which account the conversation belongs to). Passed through
     * verbatim: this side names no variable, exactly as it names no flag.
     */
    env?: Record<string, string>;
  }): Promise<void>;
  /** Switch the folder to a branch — refused when the tree is dirty. */
  switchBranch(dir: string, branch: string): Promise<BranchSwitchResult>;
  /**
   * Show one of the daemon's own files in Finder — the debug log.
   *
   * Deliberately narrow: it REVEALS (selects in a file manager) rather than
   * opens, so nothing here can be talked into executing what it is handed, and
   * main refuses any path outside the daemon's log directory. The renderer is
   * sandboxed and a path it supplies is not trusted just because the daemon
   * gave it to us.
   */
  revealPath(
    path: string,
  ): Promise<{ revealed: boolean; reason: string | null }>;
  /**
   * Toggle Chrome DevTools on this window — the same Elements / Console /
   * Network panels a browser gives you, because the renderer IS a browser.
   *
   * It answers a different question from the debug panel and neither replaces
   * the other. DevTools sees ONE process, this one: the DOM, renderer
   * exceptions, and every HTTP call and `/ws` frame the renderer sends. It
   * cannot see the daemon or a spawned CLI at all — those are separate
   * processes with no page and no renderer network stack, which is why the
   * daemon log, the transcript stream and `agent-stdio` exist in the debug
   * panel instead, and why reaching the daemon's own internals needs
   * `daemonInspect` rather than this.
   *
   * Electron's default menu already binds this to ⌥⌘I; the button exists so it
   * is findable from the place a user already looks when something is wrong.
   */
  toggleDevTools(): Promise<void>;
  /**
   * Post a system notification about a run, if the user has that kind switched
   * on. Resolves either way — a notification the settings suppressed is not a
   * failure, and the caller has nothing to do about one that was.
   */
  notify(notification: RunNotification): Promise<void>;
  /**
   * Post a banner the user explicitly asked for, and report what became of it.
   *
   * The one notification path with an ANSWER, and it needs one: every other is
   * fire-and-forget, so a user seeing no banners has no way to tell a setting
   * from a permission from a bug. It also spends the macOS authorisation prompt
   * deliberately — the system asks the first time an app posts and swallows
   * that notification to do it, so without this the first banner anyone should
   * have seen is always the one they never get.
   */
  testNotification(): Promise<{
    /** Whether the app posted at all (settings/platform can refuse first). */
    posted: boolean;
    /** What the platform reported: true shown, false refused, null silent. */
    shown: boolean | null;
    /** Why it did not arrive, in words for the user; null when it did. */
    reason: string | null;
  }>;
  /**
   * Open macOS's own Notifications pane, where an app the system is holding
   * gets un-held.
   *
   * The other half of {@link testNotification}: that one establishes that the
   * silence is the OS's doing, and this one goes to the only place the user can
   * do anything about it. It takes NO argument on purpose — the destination is
   * a constant in main, so a renderer cannot aim `shell.openExternal` at a pane
   * of its choosing.
   */
  openNotificationSettings(): Promise<void>;
  /**
   * A notification the user CLICKED, carrying the run it was about.
   *
   * The other half of `notify`: a banner you cannot act on only tells you to go
   * looking. Main raises and focuses the window; this is what lets the app open
   * the thread the banner named.
   */
  onNotificationActivated(listener: (runId: string) => void): () => void;
}

/** IPC channel names — single source of truth for main ⇄ preload wiring. */
export const IPC = {
  getStatus: 'geniro:getStatus',
  getDaemonHandle: 'geniro:getDaemonHandle',
  onDaemonRestarted: 'geniro:onDaemonRestarted',
  pickProjectFolder: 'geniro:pickProjectFolder',
  pickAgentBinary: 'geniro:pickAgentBinary',
  getSettings: 'geniro:getSettings',
  updateSettings: 'geniro:updateSettings',
  detectClis: 'geniro:detectClis',
  completeOnboarding: 'geniro:completeOnboarding',
  pickWorkflowImport: 'geniro:pickWorkflowImport',
  pickWorkflowExport: 'geniro:pickWorkflowExport',
  getUpdateState: 'geniro:getUpdateState',
  checkForUpdates: 'geniro:checkForUpdates',
  installUpdate: 'geniro:installUpdate',
  relaunchForUpdate: 'geniro:relaunchForUpdate',
  onUpdateState: 'geniro:onUpdateState',
  getGitInfo: 'geniro:getGitInfo',
  openInTerminal: 'geniro:openInTerminal',
  switchBranch: 'geniro:switchBranch',
  revealPath: 'geniro:revealPath',
  toggleDevTools: 'geniro:toggleDevTools',
  notify: 'geniro:notify',
  testNotification: 'geniro:testNotification',
  openNotificationSettings: 'geniro:openNotificationSettings',
  onNotificationActivated: 'geniro:onNotificationActivated',
} as const satisfies Record<keyof GeniroApi, string>;
